"""Embed FDSceneFix.dylib into Feather/Utilities/Handlers/FDSceneFix.swift as base64.
Usage: python3 -I gen_swift.py <FDSceneFix.dylib> <output.swift>"""
import base64, hashlib, sys, textwrap

TEMPLATE = r'''//
//  FDSceneFix.swift
//  Feather
//
//  GENERATED by Tools/FDSceneFix/build.sh - do not edit.
//  Embedded FDSceneFix.dylib (source: Tools/FDSceneFix/fdscene.c), a UIScene shim for
//  legacy AppDelegate-window apps whose SDK is forced to iOS 27 (UIScene is mandatory there).
//  Kept as base64 so the synchronized Feather group never links or copies a raw .dylib.
//

import Foundation
import CryptoKit

enum FDSceneFix {
	static let fileName = "FDSceneFix.dylib"
	static let delegateClassName = "FDSceneDelegate"
	/// iOS 27.1.0 in LC_BUILD_VERSION encoding (xxxx.yy.zz nibbles).
	static let sdk27_1: UInt32 = (27 << 16) | (1 << 8)

	static var dylibData: Data? {
		guard
			let data = Data(base64Encoded: _base64, options: .ignoreUnknownCharacters),
			SHA256.hash(data: data).map({ String(format: "%02x", $0) }).joined() == _sha256
		else {
			return nil
		}
		return data
	}

	private static let _sha256 = "@SHA256@"
	private static let _base64 = """
@BASE64@
		"""
}
'''

blob = open(sys.argv[1], 'rb').read()
lines = "\n".join("\t\t" + line for line in textwrap.wrap(base64.b64encode(blob).decode(), 100))
src = TEMPLATE.replace("@SHA256@", hashlib.sha256(blob).hexdigest()).replace("@BASE64@", lines)
open(sys.argv[2], 'w').write(src)
print(f"wrote {sys.argv[2]} ({len(blob)} bytes dylib)")
